<template><ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/home" /></ion-buttons><ion-title>Sobre</ion-title></ion-toolbar></ion-header><ion-content class="ion-padding"><main class="about"><ion-icon :icon="imagesOutline" color="primary" /><h1>Minha Galeria</h1><p>Versão {{ version }}</p><ion-list inset><ion-item><ion-label><h2>Conexão</h2><p :class="online ? 'online' : 'offline'">{{ online ? 'Internet disponível' : 'Sem conexão com a internet' }}</p></ion-label></ion-item><ion-item button @click="loadLocation"><ion-label><h2>Minha localização</h2><p v-if="location">Latitude: {{ location.latitude.toFixed(6) }}<br>Longitude: {{ location.longitude.toFixed(6) }}<br>Altitude: {{ location.altitude === null ? 'Indisponível' : `${location.altitude.toFixed(1)} m` }}</p><p v-else>{{ locationError || 'Obtendo localização...' }}</p></ion-label></ion-item><ion-item><ion-label>Modo escuro</ion-label><ion-toggle slot="end" v-model="darkMode" @ion-change="changeTheme" /></ion-item><ion-item button detail @click="router.push('/termos/uso')"><ion-icon slot="start" :icon="documentTextOutline" /><ion-label>Termos de uso</ion-label></ion-item><ion-item button detail @click="router.push('/termos/privacidade')"><ion-icon slot="start" :icon="shieldCheckmarkOutline" /><ion-label>Termos de privacidade</ion-label></ion-item></ion-list></main></ion-content></ion-page></template>
<script setup lang="ts">import { onMounted, onUnmounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { Geolocation } from '@capacitor/geolocation'; import { getDarkMode, setDarkMode } from '@/services/settings'; import { IonBackButton, IonButtons, IonContent, IonHeader, IonIcon, IonItem, IonLabel, IonList, IonPage, IonTitle, IonToggle, IonToolbar } from '@ionic/vue'; import { documentTextOutline, imagesOutline, shieldCheckmarkOutline } from 'ionicons/icons'; const router = useRouter(); const version = import.meta.env.VITE_APP_VERSION ?? '1.0.0'; const darkMode = ref(false); const online = ref(navigator.onLine); const location = ref<{ latitude: number; longitude: number; altitude: number | null } | null>(null); const locationError = ref(''); async function loadLocation() { locationError.value = ''; try { const permission = await Geolocation.requestPermissions(); if (permission.location !== 'granted' && permission.coarseLocation !== 'granted') throw new Error('Permissão de localização negada.'); const position = await Geolocation.getCurrentPosition({ enableHighAccuracy: true, timeout: 10000 }); location.value = { latitude: position.coords.latitude, longitude: position.coords.longitude, altitude: position.coords.altitude }; } catch (error) { locationError.value = error instanceof Error && error.message === 'Permissão de localização negada.' ? error.message : 'Não foi possível obter a localização.'; } } async function changeTheme() { await setDarkMode(darkMode.value); } function updateOnline() { online.value = navigator.onLine; } onMounted(async () => { darkMode.value = await getDarkMode(); window.addEventListener('online', updateOnline); window.addEventListener('offline', updateOnline); await loadLocation(); }); onUnmounted(() => { window.removeEventListener('online', updateOnline); window.removeEventListener('offline', updateOnline); });</script>
<style scoped>.about { max-width: 500px; margin: 30px auto; text-align: center; }.about > ion-icon { font-size: 74px; }.about h1 { margin-bottom: 2px; }.about p { color: #64748b; }.about ion-list { text-align: left; }.online { color: var(--ion-color-success) !important; }.offline { color: var(--ion-color-danger) !important; }</style>
